RSpec.describe "Timekeeping reservations tenant isolation: foreign entries at prepare" do
  include_context "timekeeping entry writes"

  it "answers another company's entry as not_found and reserves nothing in either company" do
    client = TimekeepingRackClient.new(Rails.application)
    operations = %w[prepare commit abort mark_billed detach_entries]
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    own_entry = timekeeping_arrange.entry(company:, user:, project: timekeeping_arrange.project(company:))
    foreign_user = timekeeping_arrange.user(company: other_company, role: "employee")
    foreign_entry = timekeeping_arrange.entry(company: other_company, user: foreign_user,
                                              project: timekeeping_arrange.project(company: other_company))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations:)

    # "not_found covers an entry outside company_id, so a caller cannot probe other tenants" (section 5.3);
    # the issue: "-> 409 { reason: "conflict", ... } (nothing reserved)".
    response = client.call("POST", "/v1/companies/#{company}/reservations/prepare",
                           headers: { "Authorization" => "Bearer #{service}" },
                           body: { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active",
                                   "generation" => timekeeping_arrange.current_generation,
                                   "entries" => [own_entry, foreign_entry] })

    expect(response.status).to eq(409)
    expect(response.body).to eq("reason" => "conflict",
                                "conflicts" => [{ "entry_id" => foreign_entry, "reason" => "not_found" }])
    expect(Reservation.where(entry_id: [own_entry, foreign_entry]).count).to eq(0)
    expect(timekeeping_arrange.reservations_for(foreign_entry)).to eq([])
    expect(timekeeping_arrange.entry_locked(foreign_entry)).to be(false)
  end
end

RSpec.describe "Timekeeping reservations tenant isolation: credential bound to another company" do
  include_context "timekeeping entry writes"

  it "refuses a service bound to another company with not_found before writing anything" do
    client = TimekeepingRackClient.new(Rails.application)
    operations = %w[prepare commit abort mark_billed detach_entries]
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    entry = timekeeping_arrange.entry(company:, user:, project:)
    agent_entry = timekeeping_arrange.entry(company:, user:, project:, agent_id: 77)
    billable = timekeeping_arrange.reserved_entry(company:, invoice_id: 501, state: "committed")
    other_service = timekeeping_arrange.service_identity(company: other_company, name: "invoice-boundary", operations:)
    generation = timekeeping_arrange.current_generation
    counts = -> { [Reservation.count, AuditEvent.count, OutboxSnapshot.count, ServiceIdempotencyReceipt.count] }
    before = counts.call

    # "The background credential (`TIMEKEEPING_SERVICE_TOKEN`) is bound to one `company_id` per request"
    requests = {
      "/v1/companies/#{company}/reservations/prepare" =>
        { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active", "entries" => [entry] },
      "/v1/companies/#{company}/invoices/501/mark-billed" => { "operation_id" => SecureRandom.uuid },
      "/v1/companies/#{company}/agents/77/detach-entries" => { "operation_id" => SecureRandom.uuid }
    }
    requests.each do |path, body|
      response = client.call("POST", path, headers: { "Authorization" => "Bearer #{other_service}" },
                                           body: body.merge("generation" => generation))

      expect([path, response.status, response.body]).to eq([path, 404, { "reason" => "not_found" }])
    end

    expect(counts.call).to eq(before)
    expect(timekeeping_arrange.stored_entry(billable).fetch("bill_status")).to eq("unbilled")
    expect(timekeeping_arrange.stored_entry(agent_entry).fetch("agent_id")).to eq(77)
    expect(timekeeping_arrange.entry_locked(entry)).to be(false)
  end
end

RSpec.describe "Timekeeping reservations tenant isolation: operation ids per company" do
  include_context "timekeeping entry writes"

  it "never commits or aborts another company's operation that carries the same operation id" do
    client = TimekeepingRackClient.new(Rails.application)
    operations = %w[prepare commit abort mark_billed detach_entries]
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    entry = timekeeping_arrange.entry(company:, user:, project: timekeeping_arrange.project(company:))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations:)
    other_service = timekeeping_arrange.service_identity(company: other_company, name: "invoice-boundary", operations:)
    operation_id = SecureRandom.uuid
    post = lambda do |company_id, credential, route, body|
      client.call("POST", "/v1/companies/#{company_id}/reservations/#{route}",
                  headers: { "Authorization" => "Bearer #{credential}" },
                  body: body.merge("generation" => timekeeping_arrange.current_generation))
    end

    prepared = post.call(company, service, "prepare",
                         { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active", "entries" => [entry] })
    expect(prepared.status).to eq(200)

    # "Operation ids are unique only within a company." and "A replayed or guessed id from another company never matches."
    foreign_commit = post.call(other_company, other_service, "commit", { "invoice_id" => 501, "operation_id" => operation_id })
    foreign_abort = post.call(other_company, other_service, "abort", { "invoice_id" => 501, "operation_id" => operation_id })

    expect([foreign_commit.status, foreign_commit.body]).to eq([404, { "reason" => "not_found" }])
    expect([foreign_abort.status, foreign_abort.body]).to eq([404, { "reason" => "not_found" }])
    expect(timekeeping_arrange.reservations_for(entry)).to eq([{ "invoice_id" => 501, "state" => "provisional" }])

    own_commit = post.call(company, service, "commit", { "invoice_id" => 501, "operation_id" => operation_id })

    expect(own_commit.body).to eq("reserved" => 1, "released" => 0)
    expect(timekeeping_arrange.reservations_for(entry)).to eq([{ "invoice_id" => 501, "state" => "committed" }])
  end
end

RSpec.describe "Timekeeping reservations tenant isolation: invoice ids per company" do
  include_context "timekeeping entry writes"

  it "lets two companies each hold an unresolved operation for the same invoice id" do
    client = TimekeepingRackClient.new(Rails.application)
    operations = %w[prepare commit abort mark_billed detach_entries]
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    entry_in = lambda do |company_id|
      user = timekeeping_arrange.user(company: company_id, role: "employee")
      timekeeping_arrange.entry(company: company_id, user:, project: timekeeping_arrange.project(company: company_id))
    end
    own_entry = entry_in.call(company)
    foreign_entry = entry_in.call(other_company)
    prepare = lambda do |company_id, entry_id|
      credential = timekeeping_arrange.service_identity(company: company_id, name: "invoice-boundary", operations:)
      client.call("POST", "/v1/companies/#{company_id}/reservations/prepare",
                  headers: { "Authorization" => "Bearer #{credential}" },
                  body: { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active",
                          "generation" => timekeeping_arrange.current_generation, "entries" => [entry_id] })
    end

    first = prepare.call(company, own_entry)
    # An unresolved operation for invoice 501 in one company must not answer unresolved_operation in another.
    second = prepare.call(other_company, foreign_entry)

    expect(first.status).to eq(200)
    expect(second.status).to eq(200)
    expect(second.body.fetch("entries")).to eq([{ "entry_id" => foreign_entry, "company_id" => other_company }])
    expect(timekeeping_arrange.reservations_for(foreign_entry)).to eq([{ "invoice_id" => 501, "state" => "provisional" }])
  end
end

RSpec.describe "Timekeeping reservations tenant isolation: mark-billed per company" do
  include_context "timekeeping entry writes"

  it "bills only the path company's entries for an invoice id another company also uses" do
    client = TimekeepingRackClient.new(Rails.application)
    operations = %w[prepare commit abort mark_billed detach_entries]
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    own_entry = timekeeping_arrange.reserved_entry(company:, invoice_id: 501, state: "committed")
    foreign_entry = timekeeping_arrange.reserved_entry(company: other_company, invoice_id: 501, state: "committed")
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations:)
    foreign_audits = -> { AuditEvent.where(company_id: other_company).count }
    foreign_snapshots = -> { OutboxSnapshot.where(company_id: other_company).count }
    audits_before = foreign_audits.call
    snapshots_before = foreign_snapshots.call

    response = client.call("POST", "/v1/companies/#{company}/invoices/501/mark-billed",
                           headers: { "Authorization" => "Bearer #{service}" },
                           body: { "operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation })

    expect([response.status, response.body]).to eq([200, { "billed" => 1 }])
    expect(timekeeping_arrange.stored_entry(own_entry).fetch("bill_status")).to eq("billed")
    expect(timekeeping_arrange.stored_entry(foreign_entry).fetch("bill_status")).to eq("unbilled")
    expect([foreign_audits.call, foreign_snapshots.call]).to eq([audits_before, snapshots_before])
  end
end

RSpec.describe "Timekeeping reservations tenant isolation: detach-entries per company" do
  include_context "timekeeping entry writes"

  it "detaches the agent only from the path company's entries and audits only those" do
    client = TimekeepingRackClient.new(Rails.application)
    operations = %w[prepare commit abort mark_billed detach_entries]
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    entry_with_agent = lambda do |company_id|
      user = timekeeping_arrange.user(company: company_id, role: "employee")
      timekeeping_arrange.entry(company: company_id, user:, project: timekeeping_arrange.project(company: company_id), agent_id: 77)
    end
    own_entry = entry_with_agent.call(company)
    foreign_entry = entry_with_agent.call(other_company)
    service = timekeeping_arrange.service_identity(company:, name: "agent-destroy", operations:)

    # "Detach-entries nulls `agent_id` on that company's entries for the agent with one audit row per entry."
    response = client.call("POST", "/v1/companies/#{company}/agents/77/detach-entries",
                           headers: { "Authorization" => "Bearer #{service}" },
                           body: { "operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation })

    expect([response.status, response.body]).to eq([200, { "detached" => 1 }])
    expect(timekeeping_arrange.stored_entry(own_entry).fetch("agent_id")).to be_nil
    expect(timekeeping_arrange.stored_entry(foreign_entry).fetch("agent_id")).to eq(77)
    expect(AuditEvent.where(entry_id: own_entry).count).to eq(1)
    expect(AuditEvent.where(entry_id: foreign_entry).count).to eq(0)
    expect(OutboxSnapshot.where(company_id: other_company).count).to eq(0)
  end
end
